/* KGN V17: add-on to existing secure admin.js; no Supabase credentials here. */
(()=>{'use strict';
if(!document.querySelector('link[data-kgn-v17]')){const css=document.createElement('link');css.rel='stylesheet';css.href='./bundle.css?v=17';css.dataset.kgnV17='';document.head.append(css);}
const SIZES=['0-0','16-18','20-24','26-30','32-34','S','M','L','XL','XXL','32-40','28-32','34-36','20-30'];
const PACKS=[3,4,5,6];
const q=id=>document.getElementById(id);
const ui=document.createElement('section');ui.className='kgn-pack-editor';ui.innerHTML=`<h3>📏 Size & Bundle सेट करें</h3><p class="kgn-help">एक या कई Sizes और Pack Buttons चुनें। 3 और 6 दोनों चुन सकते हैं। 20-30 Size में केवल 6 Piece मान्य है।</p><div class="kgn-option-title">📏 उपलब्ध Size (Multi-select)</div><div id="kgnSizeButtons" class="kgn-chip-grid"></div><div class="kgn-option-title">📦 बिक्री के Bundle (Multi-select)</div><div id="kgnPackButtons" class="kgn-chip-grid"></div><p id="kgnPackSummary" class="kgn-help" aria-live="polite"></p>`;
let currentSizes=[],currentPacks=[];
function draw(){const size=q('kgnSizeButtons'),pack=q('kgnPackButtons');if(!size||!pack)return;size.innerHTML=SIZES.map(v=>`<button type="button" class="kgn-chip ${currentSizes.includes(v)?'selected':''}" data-size="${v}" aria-pressed="${currentSizes.includes(v)}">${v}</button>`).join('');pack.innerHTML=PACKS.map(v=>`<button type="button" class="kgn-chip ${currentPacks.includes(v)?'selected':''}" data-pack="${v}" aria-pressed="${currentPacks.includes(v)}">📦 ${v} Piece</button>`).join('');q('kgnPackSummary').textContent='Selected: '+(currentSizes.join(', ')||'Size on enquiry')+' · '+(currentPacks.map(n=>n+' pc').join(' / ')||'Choose a pack');}
function mount(){const form=q('productForm'),unit=q('unit');if(!form||q('kgnSizeButtons'))return;const moq=q('moq');if(moq){moq.readOnly=true;moq.title='Bundle buttons से अपने आप सेट होगा';moq.placeholder='Bundle से सेट होगा';}const rate=q('rate');if(rate)rate.insertAdjacentHTML('beforebegin','<small class="kgn-help">₹ प्रति Piece/वर्तमान Price unit; Pack quantity अलग से चुनें।</small>');(unit?.closest('div.grid2')||form.querySelector('.toggles')).before(ui);ui.addEventListener('click',e=>{const s=e.target.closest('[data-size]'),p=e.target.closest('[data-pack]');if(s){const v=s.dataset.size;currentSizes=currentSizes.includes(v)?currentSizes.filter(x=>x!==v):[...currentSizes,v];if(currentSizes.includes('20-30'))currentPacks=currentPacks.filter(v=>v===6);}if(p){const v=Number(p.dataset.pack);if(currentSizes.includes('20-30')&&v!==6){alert('20-30 Size में केवल 6 Piece Bundle बेचा जा सकता है।');return;}currentPacks=currentPacks.includes(v)?currentPacks.filter(n=>n!==v):(v===4||v===5)?[v]:currentPacks.filter(n=>n!==4&&n!==5).concat(v);}currentPacks.sort((a,b)=>a-b);if(moq)moq.value=currentPacks[0]||'';draw();});draw();}
function install(){mount();if(typeof window.openEditor!=='function'||typeof window.formPayload!=='function')return;
const originalOpen=window.openEditor;window.openEditor=function(id=null){originalOpen(id);const p=typeof products!=='undefined'?products.find(x=>x.id===id):null;currentSizes=Array.isArray(p?.size_options)?p.size_options.filter(s=>SIZES.includes(s)):[];currentPacks=Array.isArray(p?.pack_options)&&p.pack_options.length?p.pack_options.filter(n=>PACKS.includes(n)):PACKS.includes(Number(p?.moq))?[Number(p.moq)]:[];if(currentSizes.includes('20-30'))currentPacks=currentPacks.filter(n=>n===6);currentPacks.sort((a,b)=>a-b);const moq=q('moq');if(moq)moq.value=currentPacks[0]||p?.moq||'';draw()};
const originalPayload=window.formPayload;window.formPayload=function(){if(!currentPacks.length)throw Error('कम से कम एक 📦 Bundle चुनें।');if(currentSizes.includes('20-30')&&currentPacks.some(n=>n!==6))throw Error('20-30 में केवल 6 Piece चुनें।');const moq=q('moq');if(moq)moq.value=Math.min(...currentPacks);const row=originalPayload();row.size_options=[...currentSizes];row.pack_options=[...currentPacks];row.moq=Math.min(...currentPacks);return row;};
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
